solution:
fn count_functions(source: Str) -> Int {
  var count = 0;
  var pos = 0;
  while pos < source.len() {
    if source[pos..].starts_with("fn ") {
      count = count + 1;
    }
    pos = pos + 1;
  }
  return count;
}

fn main() -> Int {
  let code = "fn a() {} fn b() {} fn c() {}";
  return count_functions(code);
}
